/* ---- chat dock (docked right; collapses to a rail) ---- */
window.guardApply = function(f){
  if(f.hasAttribute('data-no-busy')) return true;
  var b = f.querySelector('button[type=submit]');
  if(!b || b.disabled) return false;
  b.dataset.busy = '1';
  b._busyPrev = b.textContent;
  b.disabled = true;
  b.textContent = f.getAttribute('data-busy-label') || b.getAttribute('data-busy-label') || 'Working…';
  return true;
};
window.addEventListener('pageshow', function(){
  document.querySelectorAll('button[data-busy]').forEach(function(b){
    b.disabled = false; delete b.dataset.busy;
    if(b._busyPrev){ b.textContent = b._busyPrev; b._busyPrev = null; }
  });
});
